using System;
using UnityEngine;
using Framework.Grid;

namespace Framework.CameraSystem
{
    /// <summary>
    /// グリッド全体が画面内に収まるように
    /// Orthographic Cameraを調整する汎用クラス。
    ///
    /// ゲーム固有のデータには依存せず、
    /// グリッドの範囲と座標変換情報のみを使用する。
    /// </summary>
    public static class GridCameraFitter
    {
        #region Constants

        /// <summary>カメラ表示サイズの最小値。</summary>
        public const float MinimumOrthographicSize = 0.01f;

        /// <summary>カメラ周囲の標準余白。</summary>
        public const float DefaultPadding = 1f;

        #endregion

        #region Bounds Methods

        /// <summary>
        /// 指定されたグリッド範囲のワールド座標上の
        /// 境界を取得する。
        /// </summary>
        /// <param name="converter">座標変換クラス</param>
        /// <param name="cellBounds">対象セル範囲</param>
        /// <returns>ワールド座標上の境界</returns>
        public static Bounds GetWorldBounds(
            GridCoordinateConverter converter,
            RectInt cellBounds)
        {
            if (converter == null)
            {
                throw new ArgumentNullException(
                    nameof(converter));
            }

            if (cellBounds.width <= 0 ||
                cellBounds.height <= 0)
            {
                throw new ArgumentException(
                    "グリッド範囲は正の大きさが必要です。",
                    nameof(cellBounds));
            }

            // グリッド範囲の四隅をワールド座標へ変換する。
            Vector3 bottomLeft = converter.CellToWorld(
                new Vector2Int(
                    cellBounds.xMin,
                    cellBounds.yMin));

            Vector3 bottomRight = converter.CellToWorld(
                new Vector2Int(
                    cellBounds.xMax,
                    cellBounds.yMin));

            Vector3 topLeft = converter.CellToWorld(
                new Vector2Int(
                    cellBounds.xMin,
                    cellBounds.yMax));

            Vector3 topRight = converter.CellToWorld(
                new Vector2Int(
                    cellBounds.xMax,
                    cellBounds.yMax));

            // 四隅を含むワールド座標上の境界を構築する。
            Bounds bounds = new Bounds(
                bottomLeft,
                Vector3.zero);

            bounds.Encapsulate(bottomRight);
            bounds.Encapsulate(topLeft);
            bounds.Encapsulate(topRight);

            return bounds;
        }

        /// <summary>
        /// グリッドマップ全体のワールド境界を取得する。
        /// </summary>
        /// <typeparam name="T">セルデータの型</typeparam>
        /// <param name="converter">座標変換クラス</param>
        /// <param name="map">対象グリッドマップ</param>
        /// <returns>ワールド座標上の境界</returns>
        public static Bounds GetWorldBounds<T>(
            GridCoordinateConverter converter,
            GridMap<T> map)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            return GetWorldBounds(
                converter,
                map.Bounds);
        }

        #endregion

        #region Calculation Methods

        /// <summary>
        /// 指定範囲を画面内に収めるために必要な
        /// Orthographic Sizeを計算する。
        /// </summary>
        /// <param name="width">対象範囲の横幅</param>
        /// <param name="height">対象範囲の高さ</param>
        /// <param name="aspect">画面の横幅と高さの比率</param>
        /// <param name="padding">各辺の余白</param>
        /// <returns>必要なOrthographic Size</returns>
        public static float CalculateOrthographicSize(
            float width,
            float height,
            float aspect,
            float padding = DefaultPadding)
        {
            ValidateNonNegative(width, nameof(width));
            ValidateNonNegative(height, nameof(height));
            ValidateNonNegative(padding, nameof(padding));

            if (float.IsNaN(aspect) ||
                float.IsInfinity(aspect) ||
                aspect <= 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(aspect));
            }

            // 左右・上下それぞれに余白を追加する。
            float paddedWidth = width + padding * 2f;
            float paddedHeight = height + padding * 2f;

            // 高さを基準とした表示サイズ。
            float verticalSize = paddedHeight * 0.5f;

            // 横幅を基準とした表示サイズ。
            float horizontalSize =
                paddedWidth / (2f * aspect);

            // 両方の条件を満たす大きい方を採用する。
            float requiredSize = Mathf.Max(
                verticalSize,
                horizontalSize);

            return Mathf.Max(
                MinimumOrthographicSize,
                requiredSize);
        }

        #endregion

        #region Camera Fit Methods

        /// <summary>
        /// 指定されたワールド境界にカメラを合わせる。
        ///
        /// XY平面を正面から撮影する
        /// Orthographic Cameraを対象とする。
        /// カメラのZ座標と回転は維持する。
        /// </summary>
        /// <param name="targetCamera">調整対象カメラ</param>
        /// <param name="worldBounds">対象ワールド境界</param>
        /// <param name="padding">各辺の余白</param>
        public static void Fit(
            Camera targetCamera,
            Bounds worldBounds,
            float padding = DefaultPadding)
        {
            if (targetCamera == null)
            {
                throw new ArgumentNullException(
                    nameof(targetCamera));
            }

            if (!targetCamera.orthographic)
            {
                throw new InvalidOperationException(
                    "Orthographic Cameraが必要です。");
            }

            // XY平面を正面から撮影するカメラのみ対応する。
            if (Quaternion.Angle(
                    targetCamera.transform.rotation,
                    Quaternion.identity) > 0.01f)
            {
                throw new InvalidOperationException(
                    "カメラのワールド回転を(0, 0, 0)にしてください。");
            }

            // 横幅・高さの両方を考慮して表示サイズを計算する。
            float requiredSize = CalculateOrthographicSize(
                worldBounds.size.x,
                worldBounds.size.y,
                targetCamera.aspect,
                padding);

            // 現在のZ座標を維持したまま中心位置を変更する。
            Vector3 cameraPosition =
                targetCamera.transform.position;

            cameraPosition.x = worldBounds.center.x;
            cameraPosition.y = worldBounds.center.y;

            targetCamera.transform.position = cameraPosition;
            targetCamera.orthographicSize = requiredSize;
        }

        /// <summary>
        /// 指定されたセル範囲にカメラを合わせる。
        /// </summary>
        /// <param name="targetCamera">調整対象カメラ</param>
        /// <param name="converter">座標変換クラス</param>
        /// <param name="cellBounds">対象セル範囲</param>
        /// <param name="padding">各辺の余白</param>
        public static void Fit(
            Camera targetCamera,
            GridCoordinateConverter converter,
            RectInt cellBounds,
            float padding = DefaultPadding)
        {
            Bounds worldBounds = GetWorldBounds(
                converter,
                cellBounds);

            Fit(targetCamera, worldBounds, padding);
        }

        /// <summary>
        /// グリッドマップ全体にカメラを合わせる。
        /// </summary>
        /// <typeparam name="T">セルデータの型</typeparam>
        /// <param name="targetCamera">調整対象カメラ</param>
        /// <param name="converter">座標変換クラス</param>
        /// <param name="map">対象グリッドマップ</param>
        /// <param name="padding">各辺の余白</param>
        public static void Fit<T>(
            Camera targetCamera,
            GridCoordinateConverter converter,
            GridMap<T> map,
            float padding = DefaultPadding)
        {
            Bounds worldBounds = GetWorldBounds(
                converter,
                map);

            Fit(targetCamera, worldBounds, padding);
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// 値が有限かつ0以上であることを検証する。
        /// </summary>
        /// <param name="value">検証対象の値</param>
        /// <param name="parameterName">引数名</param>
        private static void ValidateNonNegative(
            float value,
            string parameterName)
        {
            if (float.IsNaN(value) ||
                float.IsInfinity(value) ||
                value < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    parameterName);
            }
        }

        #endregion
    }
}

examples.body:
グリッドマップの生成完了後に実行する基本的な使用例です。マップ全体が画面内に収まるように、カメラの位置と表示サイズを自動調整します。
// グリッドマップ全体にカメラを合わせる。
GridCameraFitter.Fit(Camera.main, converter, map);

余白には DefaultPadding（1f）が使用されます。

マップ全体ではなく、特定のセル範囲だけを画面内に収めたい場合に使用します。
// セル座標(3, 2)から横5マス、縦4マスの範囲。
RectInt cellBounds = new RectInt(3, 2, 5, 4);

// 指定されたセル範囲にカメラを合わせる。
GridCameraFitter.Fit(
    Camera.main,
    converter,
    cellBounds,
    padding: 0.5f);

カメラを操作せず、グリッドマップのワールド座標上の中心位置やサイズを取得する場合に使用します。
// グリッドマップ全体のワールド境界を取得する。
Bounds bounds = GridCameraFitter.GetWorldBounds(
    converter,
    map);

// 中心位置とサイズを確認する。
Debug.Log($"中心座標：{bounds.center}");
Debug.Log($"横幅：{bounds.size.x}");
Debug.Log($"縦幅：{bounds.size.y}");

// 対象範囲のサイズを指定する。
float width = 15f;
float height = 11f;

// 必要なカメラサイズを計算する。
float requiredSize =
    GridCameraFitter.CalculateOrthographicSize(
        width,
        height,
        Camera.main.aspect,
        padding: 1f);

// 計算結果をカメラに反映する。
Camera.main.orthographicSize = requiredSize;

グリッドマップを使用せず、任意のワールド座標上の範囲にカメラを合わせることもできます。
// 表示範囲の中心座標。
Vector3 center = new Vector3(5f, 3f, 0f);

// 表示範囲のサイズ。
Vector3 size = new Vector3(10f, 6f, 0f);

// ワールド境界を生成する。
Bounds bounds = new Bounds(center, size);

// 指定範囲にカメラを合わせる。
GridCameraFitter.Fit(
    Camera.main,
    bounds,
    padding: 1f);

グリッドを使用しない別のゲームでも利用できる使用例です。
